function componentEditor(d,key,products,refs,canRemove){const p=products.find(x=>x.id===d['product_'+key]);return `<div class="fertilizer-component">${select('Товар','product_'+key,products,d['product_'+key]).replace('<select ',d.identity_locked?'<select disabled ':'<select ')}${select('Откуда брать','location_'+key,refs.locations||[],d['location_'+key])}${input('Норма на 1 da · '+unit(p?.base_unit),'dose_'+key,d['dose_'+key],'text','inputmode="decimal"')}<details><summary>Фото и точное количество вместо расчёта</summary>${input('ID сохранённого фото · необязательно','photo_'+key,d['photo_'+key])}${input('Точное количество · необязательно','override_'+key,d['override_'+key],'text','inputmode="decimal"')}${textarea('Основание точного количества','override_reason_'+key,d['override_reason_'+key])}</details>${canRemove&&!d.identity_locked?button('Убрать компонент','fert-remove:'+key):''}</div>`;}
